WITH prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 1 HOUR THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessionized AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, burst_id, STDDEV_SAMP(pressure) AS pressure_stddev, CORR(humidity, temp_c) AS corr_humidity_temp_c, COUNT(*) FILTER (WHERE device_code = 'DV-03') AS dv_03_rows, COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END) AS dv_02_count, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('HOUR', reading_ts) ORDER BY CORR(humidity, temp_c) DESC) AS corr_humidity_temp_c_dense_rank FROM sessionized GROUP BY DATE_TRUNC('HOUR', reading_ts), burst_id HAVING STDDEV_SAMP(pressure) >= 0;
